        const keyMap = {
          childhood: { dataKey: 'childhoods', stateKey: 'selectedChildhoods' },
          elementary: { dataKey: 'elementary', stateKey: 'selectedElementary' },
          middleSchool: { dataKey: 'middleSchool', stateKey: 'selectedMiddleSchool' },
          talents: { dataKey: 'talents', stateKey: 'selectedTalents' },
        };

        const gameState = {
          currentPage: 'page1', // page1, page2, summary
          characterName: '{{user}}',
          totalPoints: 120,
          selectedDifficulty: 'd2',
          selectedFamily: null,
          selectedClass: '1年级A班',
          selectedGender: '男',
          selectedChildhoods: ['','',''],
          selectedElementary: ['','',''],
          selectedMiddleSchool: ['','',''],
          selectedTalents: ['','','','','',''],
          attributePoints: {},
          softCapPoints: {},
          knowledgePoints: {},
          skillPoints: {},

          get baseAttributes() {
            const base = {};
            for (const key in GAME_DATA.attributes) {
              base[key] = GAME_DATA.attributes[key].base;
            }
            if (this.selectedFamily && GAME_DATA.families[this.selectedFamily]?.effects?.attr) {
              const familyEffects = GAME_DATA.families[this.selectedFamily].effects.attr;
              for (const key in familyEffects) {
                if (base[key] !== undefined) base[key] += familyEffects[key];
              }
            }
            const experiences = [
              ...this.selectedChildhoods.map(id => GAME_DATA.childhoods.find(i => i.id === id)),
              ...this.selectedElementary.map(id => GAME_DATA.elementary.find(i => i.id === id)),
              ...this.selectedMiddleSchool.map(id => GAME_DATA.middleSchool.find(i => i.id === id)),
            ];
            experiences.forEach(data => {
              if (data?.effects?.attr) {
                for (const key in data.effects.attr) {
                  if (base[key] !== undefined) base[key] += data.effects.attr[key];
                }
              }
            });
            return base;
          },

          get finalAttributes() {
            const final = { ...this.baseAttributes };
            for (const key in this.attributePoints) {
              final[key] = (final[key] || 0) + this.attributePoints[key];
            }
            return final;
          },

          get baseKnowledge() {
              const base = {};
              for (const key in GAME_DATA.knowledge) {
                  base[key] = GAME_DATA.knowledge[key].base;
              }
              const experiences = [
                  ...this.selectedChildhoods.map(id => GAME_DATA.childhoods.find(i => i.id === id)),
                  ...this.selectedElementary.map(id => GAME_DATA.elementary.find(i => i.id === id)),
                  ...this.selectedMiddleSchool.map(id => GAME_DATA.middleSchool.find(i => i.id === id)),
              ].filter(Boolean);
              experiences.forEach(data => {
                  if (data?.effects?.knowledge) {
                      if (data.effects.knowledge.all) {
                          for (const key in base) {
                              base[key] += data.effects.knowledge.all;
                          }
                      } else {
                          for (const key in data.effects.knowledge) {
                              if (base[key] !== undefined) {
                                  base[key] += data.effects.knowledge[key];
                              }
                          }
                      }
                  }
              });
              return base;
          },

          get finalKnowledge() {
            const final = { ...this.baseKnowledge };
            for (const key in this.knowledgePoints) {
                final[key] = (final[key] || 0) + this.knowledgePoints[key];
            }
            return final;
          },

          get baseSkills() {
              const base = {};
              for (const key in GAME_DATA.skills) {
                  base[key] = GAME_DATA.skills[key].base;
              }
              const items = [
                  ...this.selectedChildhoods.map(id => GAME_DATA.childhoods.find(i => i.id === id)),
                  ...this.selectedElementary.map(id => GAME_DATA.elementary.find(i => i.id === id)),
                  ...this.selectedMiddleSchool.map(id => GAME_DATA.middleSchool.find(i => i.id === id)),
                  ...this.selectedTalents.map(id => GAME_DATA.talents.find(i => i.id === id)),
              ].filter(Boolean);
              items.forEach(data => {
                  if (data?.effects?.skill) {
                      if (data.effects.skill.all) {
                          for (const key in base) {
                              base[key] += data.effects.skill.all;
                          }
                      } else {
                          for (const key in data.effects.skill) {
                              if (base[key] !== undefined) {
                                  base[key] += data.effects.skill[key];
                              }
                          }
                      }
                  }
              });
              return base;
          },

          get finalSkills() {
              const final = { ...this.baseSkills };
              for (const key in this.skillPoints) {
                  final[key] = (final[key] || 0) + this.skillPoints[key];
              }
              return final;
          },

          get spentPoints() {
            let spent = 0;
            if (this.selectedFamily) spent += GAME_DATA.families[this.selectedFamily]?.cost || 0;

            Object.values(keyMap).forEach(map => {
              this[map.stateKey].forEach(id => {
                if(!id) return;
                const item = GAME_DATA[map.dataKey].find(i => i.id === id);
                if (item) spent += item.cost;
              });
            });

            for (const key in this.attributePoints) spent += this.attributePoints[key];
            for (const key in this.softCapPoints) spent += this.softCapPoints[key] * 5;
            for (const key in this.knowledgePoints) spent += this.knowledgePoints[key];
            for (const key in this.skillPoints) spent += this.skillPoints[key];
            return spent;
          },

          get remainingPoints() {
            return this.totalPoints - this.spentPoints;
          },
        };

        const setupForm = document.getElementById('setup-form');
        const appContainer = document.getElementById('app-container');

        function renderPage() {
            console.log('renderPage called, currentPage:', gameState.currentPage);
            appContainer.classList.remove('cover-mode', 'setup-mode', 'summary-mode');
            document.querySelectorAll('.form-page').forEach(p => p.classList.remove('active'));

            if (gameState.currentPage === 'summary') {
                appContainer.classList.add('summary-mode');
            } else if (gameState.currentPage.startsWith('page')) {
                appContainer.classList.add('setup-mode');
                const activePage = document.getElementById(gameState.currentPage);
                if (activePage) {
                    activePage.classList.add('active');
                }
            } else {
                appContainer.classList.add('cover-mode');
            }
        }

        function renderAll() {
          let html = `
            <div id="page1" class="form-page">
