        function renderLifeSetupSection() {
             return `
                <div class="form-section">
                    <h3>二、人生设定</h3>
                    <div class="experience-row-container">
                        <div class="experience-row">
                            <label>请问，您希望您的人生是:</label>
                             <div class="experience-desc">${GAME_DATA.difficulties[gameState.selectedDifficulty]?.name || '---'}</div>
