                          ${selectsHtml}
                      </div>
                  `;
        }

        function getSoftCap(attrId) {
          let cap = GAME_DATA.attributes[attrId].softCap;
          cap += gameState.softCapPoints[attrId] || 0;
          gameState.selectedTalents.forEach(talentId => {
            if(!talentId) return;
            const talent = GAME_DATA.talents.find(t => t.id === talentId);
            if (talent?.effects?.softCap?.[attrId]) {
              cap += talent.effects.softCap[attrId];
            }
          });
          return cap;
        }

        function renderAttributeStep() {
          const baseAttrs = gameState.baseAttributes;
          return `
                      <div class="form-section">
                          <h3>七、属性分配</h3>
                          <div class="selection-grid">
                              ${Object.entries(GAME_DATA.attributes)
                                .map(([id, attr]) => {
                                  const baseValue = baseAttrs[id];
                                  const spent = gameState.attributePoints[id] || 0;
                                  const finalValue = baseValue + spent;
                                  const softCap = getSoftCap(id);
                                  const canIncrease = gameState.remainingPoints > 0 && finalValue < softCap;
                                  const canDecrease = finalValue > 55;
                                  const canIncreaseSoftCap = gameState.remainingPoints >= 5;
                                  const canDecreaseSoftCap = softCap > 60;

                                  return `
                                  <div class="card" style="cursor: default; text-align:center; padding: 10px;">
                                      <div class="card-name">${attr.name}</div>
                                      <div style="font-size: 1.8rem; font-weight: bold; margin: 5px 0;">${finalValue}</div>
                                      <div>
                                          <button type="button" class="nav-btn" style="padding: 5px 10px; font-size: 1rem;" data-step-action="adjustAttribute" data-id="${id}" data-amount="-1" ${!canDecrease ? 'disabled' : ''}>-</button>
                                          <button type="button" class="nav-btn" style="padding: 5px 10px; font-size: 1rem;" data-step-action="adjustAttribute" data-id="${id}" data-amount="1" ${!canIncrease ? 'disabled' : ''}>+</button>
                                      </div>
                                      <p class="card-desc" style="font-size: 0.8rem; margin-top: 8px;">基础:${baseValue}, 加点:${spent}</p>
                                      <div class="card-header" style="margin-top: 8px; justify-content: center; gap: 5px;">
                                          <span class="card-name" style="font-size: 0.8rem;">潜力</span>
                                           <div class="attribute-value">
                                              <button type="button" class="nav-btn" style="padding: 5px 8px; font-size: 0.8rem;" data-step-action="adjustSoftCap" data-id="${id}" data-amount="-1" ${!canDecreaseSoftCap ? 'disabled' : ''}>-</button>
                                              <span style="font-size: 0.9rem; font-weight: bold; width: 20px; text-align: center;">${softCap}</span>
                                              <button type="button" class="nav-btn" style="padding: 5px 8px; font-size: 0.8rem;" data-step-action="adjustSoftCap" data-id="${id}" data-amount="1" ${!canIncreaseSoftCap ? 'disabled' : ''}>+</button>
                                          </div>
                                      </div>
                                  </div>
                                  `;
                                })
                                .join('')}
                          </div>
                      </div>
                  `;
        }

        function renderKnowledgeStep() {
