          const baseSkills = gameState.baseSkills;
          return `
                      <div class="form-section">
                          <h3>八、知识技能</h3>
                          <h4 style="font-weight: normal; margin-bottom: 15px;">各科知识</h4>
                          <div class="selection-grid">
                              ${Object.entries(GAME_DATA.knowledge)
                                .map(([id, item]) => {
                                  const baseValue = baseKnowledges[id];
                                  const spent = gameState.knowledgePoints[id] || 0;
                                  const finalValue = baseValue + spent;
                                  const canIncrease = gameState.remainingPoints > 0;
                                  const canDecrease = spent > 0;
                                  return `
                                  <div class="card" style="cursor: default; text-align:center; padding: 10px;">
                                      <div class="card-name">${item.name}</div>
                                       <div style="font-size: 1.8rem; font-weight: bold; margin: 5px 0;">${finalValue}</div>
                                      <div>
                                          <button type="button" class="nav-btn" style="padding: 5px 10px; font-size: 1rem;" data-step-action="adjustKnowledge" data-type="knowledge" data-id="${id}" data-amount="-1" ${!canDecrease ? 'disabled' : ''}>-</button>
                                          <button type="button" class="nav-btn" style="padding: 5px 10px; font-size: 1rem;" data-step-action="adjustKnowledge" data-type="knowledge" data-id="${id}" data-amount="1" ${!canIncrease ? 'disabled' : ''}>+</button>
                                      </div>
                                      <p class="card-desc" style="font-size: 0.8rem; margin-top: 8px;">基础:${baseValue}, 加点: ${spent}</p>
                                  </div>`;
                                })
                                .join('')}
                          </div>
                          <h4 style="margin-top: 20px; font-weight: normal;">生活技能</h4>
                          <div class="selection-grid">
                               ${Object.entries(GAME_DATA.skills)
                                 .map(([id, item]) => {
                                   const baseValue = baseSkills[id];
                                   const spent = gameState.skillPoints[id] || 0;
                                   const finalValue = baseValue + spent;
                                   const canIncrease = gameState.remainingPoints > 0;
                                   const canDecrease = spent > 0;
                                   return `
                                  <div class="card" style="cursor: default; text-align:center; padding: 10px;">
                                      <div class="card-name">${item.name}</div>
                                      <div style="font-size: 1.8rem; font-weight: bold; margin: 5px 0;">${finalValue}</div>
                                      <div>
                                          <button type="button" class="nav-btn" style="padding: 5px 10px; font-size: 1rem;" data-step-action="adjustKnowledge" data-type="skill" data-id="${id}" data-amount="-1" ${!canDecrease ? 'disabled' : ''}>-</button>
                                          <button type="button" class="nav-btn" style="padding: 5px 10px; font-size: 1rem;" data-step-action="adjustKnowledge" data-type="skill" data-id="${id}" data-amount="1" ${!canIncrease ? 'disabled' : ''}>+</button>
                                      </div>
                                      <p class="card-desc" style="font-size: 0.8rem; margin-top: 8px;">基础:${baseValue}, 加点: ${spent}</p>
                                  </div>`;
                                 })
                                 .join('')}
                          </div>
                      </div>
                  `;
        }

        function handleAction(e) {
          const target = e.target.closest('[data-step-action]') || e.target;
          if (!target || target.classList.contains('disabled')) return;
          if (e.type === 'click' && target.tagName === 'SELECT') return;

          const { stepAction, id, type, targetPage, amount, index } = target.dataset;

          let value = target.value;

          switch (stepAction) {
            case 'selectDifficulty':
              gameState.selectedDifficulty = value;
              gameState.totalPoints = GAME_DATA.difficulties[value]?.points || 0;
              break;
            case 'selectFamily':
              gameState.selectedFamily = value;
               break;
            case 'selectExperience':
              const selectedArray = gameState[keyMap[type].stateKey];
              selectedArray[parseInt(index)] = value;
              break;
            case 'toggleExperience':
              const mapInfo = keyMap[type];
              if (!mapInfo) return;
              const talentsArray = gameState[mapInfo.stateKey];
              const talentIndex = talentsArray.indexOf(id);
              const item = GAME_DATA[mapInfo.dataKey].find(i => i.id === id);
              if (!item) return;

              if (talentIndex > -1) {
                talentsArray.splice(talentIndex, 1);
              } else {
                if (gameState.remainingPoints >= item.cost) {
                  talentsArray.push(id);
                } else {
                  alert('点数不足！');
                }
              }
              break;
            case 'adjustAttribute': {
              const currentPoints = gameState.attributePoints[id] || 0;
              const change = parseInt(amount, 10);
              const finalValue = gameState.finalAttributes[id];

              if (change > 0 && gameState.remainingPoints > 0 && finalValue < getSoftCap(id)) {
                gameState.attributePoints[id] = currentPoints + change;
              } else if (change < 0 && finalValue > 55) {
                gameState.attributePoints[id] = currentPoints + change;
              }
              break;
            }
            case 'adjustSoftCap': {
                const currentSoftCapPoints = gameState.softCapPoints[id] || 0;
                const change = parseInt(amount, 10);
                if(change > 0 && gameState.remainingPoints >= 5) {
                    gameState.softCapPoints[id] = currentSoftCapPoints + change;
                } else if (change < 0 && getSoftCap(id) > 60) {
                    gameState.softCapPoints[id] = currentSoftCapPoints + change;
                }
                break;
            }
            case 'adjustKnowledge': {
              const pointsKey = type === 'knowledge' ? 'knowledgePoints' : 'skillPoints';
              const dataKey = type === 'knowledge' ? 'knowledge' : 'skills';
              const currentPoints = gameState[pointsKey][id] || 0;
              const change = parseInt(amount, 10);
              const baseValue = GAME_DATA[dataKey][id].base;
              const finalValue = baseValue + currentPoints;

              if (change > 0 && gameState.remainingPoints > 0) {
                gameState[pointsKey][id] = currentPoints + change;
              } else if (change < 0 && finalValue > 0) {
                gameState[pointsKey][id] = currentPoints + change;
              }
              break;
            }
            case 'navigate':
              gameState.currentPage = targetPage;
              renderAll();
              return;
            case 'generate':
              gameState.currentPage = 'summary';
              renderSummaryPage();
              renderPage();
              return;
          }
          renderAll();
          updateClassInfo(gameState.selectedClass);
        }

        function bindEvents() {
          setupForm.addEventListener('change', e => {
              const target = e.target;
              if (target.matches('select')) {
                  if (target.id === 'class-select') {
                    gameState.selectedClass = target.value;
                    updateClassInfo(target.value);
                  } else {
                    handleAction({ type: 'change', target: target, dataset: target.dataset });
                  }
              }
          });
          setupForm.addEventListener('click', handleAction);
        }

        function updateClassInfo(selectedClass) {
            const display = document.getElementById('class-info-display');
            if (!display) return;

            const classData = GAME_DATA.classes;
            if (!classData) {
                display.innerHTML = '<p>班级信息加载失败。</p>';
                return;
            }

            let grade, className;
            for (const g in classData) {
                for (const c in classData[g]) {
                    if (`${g}${c}` === selectedClass) {
                        grade = g;
                        className = c;
                        break;
                    }
                }
                if (grade) break;
            }

            if (grade && className && classData[grade] && classData[grade][className]) {
                const info = classData[grade][className];
                let html = `<h4>${selectedClass}</h4>`;
                html += `<p><strong>班主任:</strong> ${info.班主任 || '未指定'}</p>`;
                if (info.学生列表 && info.学生列表.length > 0) {
                    html += `<p><strong>学生列表:</strong></p><ul>`;
                    info.学生列表.forEach(student => {
                        html += `<li>${student}</li>`;
                    });
                    html += `</ul>`;
                } else {
                    html += '<p>暂无学生信息。</p>';
                }
                display.innerHTML = html;
            } else {
                display.innerHTML = `<p>未找到班级“${selectedClass}”的详细信息。</p>`;
            }
        }

        function renderSummaryPage() {
            const content = document.getElementById('summary-document-content');
            if (!content) return;

            const family = GAME_DATA.families[gameState.selectedFamily];
            const experiences = [
                ...gameState.selectedChildhoods.map(id => GAME_DATA.childhoods.find(i => i.id === id)),
                ...gameState.selectedElementary.map(id => GAME_DATA.elementary.find(i => i.id === id)),
                ...gameState.selectedMiddleSchool.map(id => GAME_DATA.middleSchool.find(i => i.id === id)),
            ].filter(Boolean);
            const talents = gameState.selectedTalents.map(id => GAME_DATA.talents.find(t => t.id === id)).filter(Boolean);

            let html = `
                <h1>天华学园新生档案</h1>
                <div class="summary-section">
                    <h2>基本信息</h2>
                    <p><strong>姓名:</strong> ${gameState.characterName}</p>
                    <p><strong>性别:</strong> ${gameState.selectedGender}</p>
                    <p><strong>班级:</strong> ${gameState.selectedClass}</p>
                </div>
                <div class="summary-section">
                    <h2>人生轨迹</h2>
                    <ul>
                        <li><strong>家庭背景:</strong> ${family ? family.name + ' - ' + family.desc : '未选择'}</li>
                        <li><strong>成长经历:</strong>
                            <ul>
                                ${experiences.map(e => `<li>${e.name}: ${e.desc}</li>`).join('') || '<li>无</li>'}
                            </ul>
                        </li>
                        <li><strong>天赋特长:</strong>
                             <ul>
                                ${talents.map(t => `<li>${t.name}: ${t.desc}</li>`).join('') || '<li>无</li>'}
                            </ul>
                        </li>
                    </ul>
                </div>
                 <div id="signature-section">
                    <p>本人确认以上信息无误。</p>
                    <p>签名: <span id="signature-line">【点击此处进行签名】</span></p>
                </div>
            `;
            content.innerHTML = html;
            document.getElementById('signature-line').addEventListener('click', animateSignature, { once: true });
        }

        function animateSignature() {
            const signatureLine = document.getElementById('signature-line');
            if (!signatureLine) return;
            signatureLine.textContent = '';
            signatureLine.style.cursor = 'default';

            const name = gameState.characterName;
            let i = 0;
            const interval = setInterval(() => {
                if (i < name.length) {
                    signatureLine.textContent += name[i];
                    i++;
                } else {
                    clearInterval(interval);
                    // Add a short delay before starting the game
                    setTimeout(() => {
                        generateStartupPrompt();
                    }, 800);
                }
            }, 150);
        }

        async function generateStartupPrompt() {
          const loadingOverlay = document.getElementById('loading-overlay');
          loadingOverlay.innerHTML = '<p>正在办理入学手续，请稍候...</p>';
          loadingOverlay.style.display = 'flex';

          const finalAttributes = gameState.finalAttributes;
          const attributesText = Object.entries(finalAttributes)
            .map(([key, value]) => {
              const softCap = getSoftCap(key);
              const expCap = 1000 * Math.pow(1.1, value - 60);
              return `              - ${GAME_DATA.attributes[key].name}: { "值": ${value}, "经验值": 0, "经验上限": ${Math.round(expCap)}, "软上限": ${softCap} }`;
            })
            .join('\n');

          const finalKnowledges = gameState.finalKnowledge;
          const knowledgeText = Object.entries(finalKnowledges)
            .map(([key, finalValue]) => {
                const expCap = 100 + Math.pow(finalValue, 1.5);
                return `              - ${GAME_DATA.knowledge[key].name}: { "知识水平": ${finalValue}, "经验值": 0, "经验上限": ${Math.round(expCap)}, "最近一次分数": 0, "年级排名": 0 }`;
            })
            .join('\n');

          const finalSkills = gameState.finalSkills;
          const skillsText = Object.entries(finalSkills)
            .map(([key, finalValue]) => {
                const expCap = 100 * Math.pow(finalValue, 2);
                return `              - ${GAME_DATA.skills[key].name}: { "等级": ${finalValue}, "经验值": 0, "经验上限": ${Math.round(expCap)}, "软上限": 5 }`;
            })
            .join('\n');

          const familyText =
            gameState.selectedFamily === 'custom'
              ? `              - ${gameState.customFamily.name}: ${gameState.customFamily.desc}`
              : gameState.selectedFamily
                ? `              - ${GAME_DATA.families[gameState.selectedFamily].name}: ${GAME_DATA.families[gameState.selectedFamily].desc}`
                : '              - 无';

          const experiencesText = [
            ...gameState.selectedChildhoods.map(id => GAME_DATA.childhoods.find(i => i.id === id)),
            ...gameState.selectedElementary.map(id => GAME_DATA.elementary.find(i => i.id === id)),
            ...gameState.selectedMiddleSchool.map(id => GAME_DATA.middleSchool.find(i => i.id === id)),
          ]
            .filter(Boolean)
            .map(item => `              - ${item.name}: ${item.desc}`)
            .join('\n');

          const talentsText = gameState.selectedTalents
            .filter(Boolean)
            .map(id => {
              const talentInfo = GAME_DATA.talents.find(t => t.id === id);
              return `              - ${talentInfo.name}: ${talentInfo.desc}`;
            })
            .join('\n');

          const userInput = `
       - **姓名**: {{user}}
       - **性别**: ${gameState.selectedGender}
       - **班级**: ${gameState.selectedClass}
       - **身份**: ${gameState.selectedClass.startsWith('1年级') ? '新生' : '转校生'}
       - **家庭背景**:
      ${familyText}
       - **成长经历**:
      ${experiencesText || '              - 无'}
       - **最终属性**:
      ${attributesText}
       - **知识与技能**:
      ${knowledgeText}
      ${skillsText}
       - **所选天赋**:
      ${talentsText || '              - 无'}
      `.trim();

          const prompt = `<开局设定>
# 角色开局设定
1.  **核心任务**: 根据下方提供的“玩家输入”，为“天华校园”世界生成开局故事和角色初始变量。
2.  **故事要求**: 生成一段充满日式校园生活气息的开局故事，描述角色办理完入学手续，正式踏入天华学园的第一天。故事必须包含在 \`<gametxt>\` 标签内。
3.  **变量生成规则**:
    *   你必须生成一个完整的 \`<UpdateVariable>\` 代码块。
    *   **严禁硬编码**: 不要直接复制玩家输入中的数值。你必须根据文本描述，自行判断并生成符合 \`[InitVar]\` 规范的变量。
    *   **设置初始时间**: 必须将 \`世界状态.当前时间\` 设置为开学日期（2024年4月8日，星期二，早上8点）。
    *   **扁平化结构**: 所有角色属性都必须是 \`角色.{{user}}\` 下的直接子属性，严禁创建“基础属性”、“核心资源”等多余的层级。
    *   **复合对象**: 对于“智商”、“数学”等属性，必须生成包含“值”、“经验值”、“经验上限”、“软上限”等字段的完整复合对象。
    *   **数组**: 对于“天赋特长”等属性，必须将每个天赋作为一个独立对象存入数组中。
    *   **指令**: 只能使用 \`_.assign\` 和 \`_.set\` 指令。
    *   **创建角色**: 任何新角色的创建，都**必须**使用 \`_.assign('角色', '<npc_id>', { ... })\` 指令一次性完整创建，数据结构需严格参考 \`[InitVar]\`。
4.  **初始社交关系 (酌情)**:
    *   分析玩家的“家庭背景”和“成长经历”，如果能与 \`[世界观]全校名册\` 中的角色产生强关联，可以酌情生成0-2个初始联系人或群组。
    *   如果生成关系，必须在 \`<NewSocialContent>\` 块中先生成对应的 \`[接受好友|...]\` 或 \`[群聊创建|...]\` 指令，然后再生成 \`[私聊|...]\` 或 \`[群聊|...]\` 指令，前端会自动处理后续的变量创建。**你严禁在 \`<UpdateVariable>\` 中直接创建NPC或关系变量。**

## 玩家输入
${userInput}
</开局设定>`;

          try {
            const generateConfig = {
              injects: [
                {
                  role: 'user',
                  content: prompt,
                  position: 'before_char',
                  should_write_to_chat: false,
                  should_scan: true,
                },
              ],
              should_stream: false,
            };
            const aiResponse = await TavernHelper.generate(generateConfig);

            if (!aiResponse) {
              throw new Error('AI未能生成开局脚本。');
            }

            const updateScriptMatch = aiResponse.match(/<UpdateVariable>([\s\S]+?)<\/UpdateVariable>/i);
            const updateScript = updateScriptMatch ? updateScriptMatch[1].trim() : null;

            const messages = await getChatMessages('0');
            if (!messages || messages.length === 0) {
              throw new Error('无法获取到第0层消息，无法写入开局设定。');
            }
            const messageZero = messages[0];

            // 使用当前消息层的数据作为旧变量
            const inputData = { old_variables: messageZero.data || {} };

            if (updateScript) {
              await eventEmit('mag_invoke_mvu', updateScript, inputData);
            }

            messageZero.message = aiResponse;
            if (inputData.new_variables) {
              messageZero.data = inputData.new_variables;
            }

            await TavernHelper.setChatMessages([messageZero], { refresh: 'all' });
          } catch (error) {
            console.error('创建角色失败:', error);
            alert(`创建角色失败: ${error.message}`);
          } finally {
            loadingOverlay.style.display = 'none';
          }
        }

        async function clearSocialData() {
          const lorebookKeysToClear = [
            '剧情摘要', '聊天记录-总结',
            '聊天群组-主', '聊天群组-辅',
            '聊天会话列表-主', '聊天会话列表-辅',
            'MX空间-主', 'MX空间-辅',
            '校园日志-主', '校园日志-辅',
            '日记总结-小-主', '日记总结-大-主',
            '课程表-主',
            '存档-手动-1', '存档-手动-2', '存档-手动-3', '存档-手动-4', '存档-手动-5',
            '存档-自动-A', '存档-自动-B'
          ];
          const localStorageKey = 'tianhua_character_state';
          const bookName = '天华校园';
          const loadingOverlay = document.getElementById('loading-overlay');

          if (
            !confirm(
              `你确定要清除所有游戏数据吗？\n\n此操作将清空以下内容：\n- 所有社交、日志、日记总结\n- 课程表\n- 所有存档\n- 浏览器缓存\n\n此操作不可撤销，将导致你从头开始新游戏！`,
            )
          ) {
            return;
          }

          loadingOverlay.style.display = 'flex';
          loadingOverlay.innerHTML = '<p>正在清除数据...</p>';

          try {
            const allEntries = await TavernHelper.getLorebookEntries(bookName);
            const entriesToUpdate = [];
            for (const key of lorebookKeysToClear) {
              const entry = allEntries.find(e => e.comment === key);
              if (entry) {
                entriesToUpdate.push({ uid: entry.uid, content: '' });
              }
            }

            if (entriesToUpdate.length > 0) {
              await TavernHelper.setLorebookEntries(bookName, entriesToUpdate);
            }
            localStorage.removeItem(localStorageKey);
            alert('所有游戏数据（社交、日志、存档、缓存等）已全部清空！');
          } catch (error) {
            console.error('清空数据时出错:', error);
            alert(`操作失败: ${error.message}`);
          } finally {
            loadingOverlay.style.display = 'none';
          }
        }

        function parseRosterData(rosterText) {
            console.log('Parsing roster data...');
            const schoolData = {};
            if (!rosterText) {
                console.error('rosterText is empty');
                return schoolData;
            }

            const gradeRegex = /\*\*(\d+年级)\*\*:\s*\{([\s\S]*?)(?=\*\*|$)/g;
            let gradeMatch;

            while ((gradeMatch = gradeRegex.exec(rosterText)) !== null) {
                const gradeName = gradeMatch[1];
                const gradeContent = gradeMatch[2];
                schoolData[gradeName] = {};

                const classHeaderRegex = /^\s*(\d+年[A-E]班(?:\s*\([^)]+\))?):\s*\{/gm;
                let classHeaderMatch;

                // We need to reset lastIndex for each gradeContent
                classHeaderRegex.lastIndex = 0;

                while((classHeaderMatch = classHeaderRegex.exec(gradeContent)) !== null) {
                    const fullClassName = classHeaderMatch[1];
                    const simpleClassName = fullClassName.replace(/^\d+年/, '');
                    const startIndex = classHeaderMatch.index + classHeaderMatch[0].length;

                    let openBraces = 1;
                    let endIndex = startIndex;

                    while(openBraces > 0 && endIndex < gradeContent.length) {
                        if(gradeContent[endIndex] === '{') openBraces++;
                        if(gradeContent[endIndex] === '}') openBraces--;
                        endIndex++;
                    }

                    const classContent = gradeContent.substring(startIndex, endIndex - 1);

                    const teacherMatch = classContent.match(/班主任:\s*'([^']+)'/);
                    const studentsMatch = classContent.match(/学生列表:\s*\{([\s\S]*?)\}/);

                    const classInfo = {
                        '班主任': teacherMatch ? teacherMatch[1] : '未指定',
                        '学生列表': []
                    };

                    if (studentsMatch) {
                        const studentListText = studentsMatch[1];
                        const studentMatches = studentListText.matchAll(/\d+\.\s*(.+)/g);
                        for (const student of studentMatches) {
                            classInfo['学生列表'].push(student[1].replace(/,$/, '').trim());
                        }
                    }
                    schoolData[gradeName][simpleClassName] = classInfo;
                }
            }
            console.log('Parsed school data:', schoolData);
            return schoolData;
        }


        async function init() {
          try {
            const allEntries = await TavernHelper.getLorebookEntries('天华校园');
            const rosterEntry = allEntries.find(e => e.comment === '[世界观]全校名册');
            if (rosterEntry) {
                GAME_DATA.classes = parseRosterData(rosterEntry.content);
            } else {
                console.error("在世界书 '天华校园' 中未找到条目 '[世界观]全校名册'");
                GAME_DATA.classes = {};
            }
          } catch (e) {
            console.error("加载或解析全校名册失败:", e);
            GAME_DATA.classes = {}; // Provide a fallback
          }

          try {
            const characterName = await TavernHelper.getCharData('user');
            gameState.characterName = characterName || '{{user}}';
            document.getElementById('admission-greeting').textContent = `亲爱的 ${gameState.characterName} 同学：`;
          } catch (e) {
            console.error("Failed to get user's character name", e);
            document.getElementById('admission-greeting').textContent = `亲爱的 {{user}} 同学：`;
          }

          document.getElementById('start-setup-btn').addEventListener('click', () => {
            console.log('Start setup button clicked');
            gameState.currentPage = 'page1';
            renderAll();
            bindEvents();
          });
          document.getElementById('clear-data-btn').addEventListener('click', clearSocialData);
        }

        document.addEventListener('DOMContentLoaded', init);
      })();
    </script>
  </body>
</html>


