                    <button type="button" class="submit-btn" data-step-action="generate" ${gameState.remainingPoints < 0 ? 'disabled' : ''}>完成建档</button>
                </div>
            </div>
          `;
          setupForm.innerHTML = html;
          renderPage();
          updatePointsTracker();
          updateClassInfo(gameState.selectedClass);
        }

