        function renderExperienceStep(stepName, title, data, selectedData) {
          let selectsHtml = '<div class="experience-row-container">';
          for (let i = 0; i < 3; i++) {
              const selectedValue = selectedData[i] || '';
              const selectedItem = data.find(item => item.id === selectedValue);

              let options = data.map(item => 
                  `<option value="${item.id}" 
                      ${selectedValue === item.id ? 'selected' : ''} 
                      ${selectedData.includes(item.id) && selectedValue !== item.id ? 'disabled' : ''}>
                      ${item.name} (${item.cost >= 0 ? `消耗${item.cost}`: `获得${-item.cost}`}点)
                  </option>`
              ).join('');

              selectsHtml += `
                <div class="experience-row">
                    <label>您的${title.substring(2,4)}:</label>
                    <div class="experience-desc">${selectedItem ? selectedItem.desc : '---'}</div>
                    <select data-step-action="selectExperience" data-type="${stepName}" data-index="${i}" style="opacity: 0; position: absolute; left: 110px; width: calc(100% - 110px);">
                        <option value="">---</option>
                        ${options}
                    </select>
                </div>
              `;
          }
          selectsHtml += '</div>';

          return `
              <div class="form-section">
                  <h3>${title}</h3>
                  ${selectsHtml}
              </div>
          `;
        }


