        function getSoftCap(attrId) {
          let cap = GAME_DATA.attributes[attrId].softCap;
          cap += gameState.softCapPoints[attrId] || 0;
          gameState.selectedTalents.forEach(talentId => {
            if(!talentId) return;
            const talent = GAME_DATA.talents.find(t => t.id === talentId);
            if (talent?.effects?.softCap?.[attrId]) {
              cap += talent.effects.softCap[attrId];
            }
          });
          return cap;
        }

