                                          <button type="button" class="nav-btn" style="padding: 5px 10px; font-size: 1rem;" data-step-action="adjustKnowledge" data-type="knowledge" data-id="${id}" data-amount="1" ${!canIncrease ? 'disabled' : ''}>+</button>
